const items = $input.all();
const lens = $('Daily — Capture Lens Context').first().json;
const MAX_AGE_DAYS = 14;
const cutoffMs = Date.now() - MAX_AGE_DAYS * 24 * 60 * 60 * 1000;

function parsePageAge(raw) {
  if (!raw) return null;
  const s = String(raw).trim();
  // Absolute (ISO, "October 30, 2025", any format Date can parse).
  const abs = new Date(s).getTime();
  if (Number.isFinite(abs)) return abs;
  // Relative: "5 days ago", "2 weeks ago", "1 hour ago", etc.
  const m = s.match(/^(\d+)\s+(second|minute|hour|day|week|month|year)s?\s+ago$/i);
  if (m) {
    const n = parseInt(m[1], 10);
    const unit = m[2].toLowerCase();
    const msPer = {
      second: 1000, minute: 60000, hour: 3600000,
      day: 86400000, week: 604800000,
      month: 2592000000, year: 31536000000,
    };
    return Date.now() - n * msPer[unit];
  }
  return null;
}
const urls = [];
const seen = new Set();
let droppedOld = 0, droppedNoDate = 0;
for (const item of items) {
  const groups = item.json.allResults ?? (item.json.results ? [item.json] : []);
  for (const group of groups) {
    const results = group.results || group.web_results || [];
    for (const r of results) {
      if (typeof r?.url !== 'string') continue;
      if (!r.url.startsWith('https://')) continue;
      if (seen.has(r.url)) continue;
      // Perplexity returns `date` (and sometimes `last_updated`) per result.
      // Drop results with no date — strong signal of listing/tag/landing page.
      const pubStr = r.date || r.published || r.last_updated;
      if (!pubStr) { droppedNoDate++; continue; }
      const pubMs = parsePageAge(pubStr);
      if (pubMs === null) { droppedNoDate++; continue; }
      if (pubMs < cutoffMs) { droppedOld++; continue; }
      seen.add(r.url);
      const sourceDate = new Date(pubMs).toISOString();
      urls.push({ url: r.url, source_date: sourceDate });
    }
  }
}
const cap = Number(lens.cap || 25);
const capped = urls.slice(0, cap);
return [{ json: { lensId: lens.lensId, lensKey: lens.lensKey, startedAt: lens.startedAt, sourceName: lens.sourceName, sourceCategory: lens.sourceCategory, urlsEmitted: capped.length, urls: capped, droppedOld, droppedNoDate } }];

const item = $input.first();
const lens = $('Daily — Capture Lens Context').first().json;
const content = (item.json.content || []);
const MAX_AGE_DAYS = 14;
const cutoffMs = Date.now() - MAX_AGE_DAYS * 24 * 60 * 60 * 1000;

function parsePageAge(raw) {
  if (!raw) return null;
