  if (m) {
    const n = parseInt(m[1], 10);
    const unit = m[2].toLowerCase();
    const msPer = {
      second: 1000, minute: 60000, hour: 3600000,
      day: 86400000, week: 604800000,
      month: 2592000000, year: 31536000000,
    };
    return Date.now() - n * msPer[unit];
  }
  return null;
}

// Anthropic's web_search returns a mix of absolute ("April 27, 2026") and
// relative ("5 days ago") page_age values. parsePageAge handles both —
// fresh URLs with relative ages were previously droppedNoDate.
const pageAgeByUrl = new Map();
for (const block of content) {
  if (block.type !== 'web_search_tool_result') continue;
  const results = Array.isArray(block.content) ? block.content : [];
  for (const r of results) {
    if (r && typeof r.url === 'string' && (r.page_age || r.date)) {
      pageAgeByUrl.set(r.url, r.page_age || r.date);
    }
  }
}

const urls = [];
const seen = new Set();
let droppedOld = 0, droppedNoDate = 0;
for (const block of content) {
  if (block.type !== 'text' || typeof block.text !== 'string') continue;
  const match = block.text.match(/\{[\s\S]*?"urls"[\s\S]*?\}/);
  if (!match) continue;
  try {
    const parsed = JSON.parse(match[0]);
    for (const u of (parsed.urls || [])) {
      if (typeof u !== 'string') continue;
      if (!u.startsWith('https://')) continue;
      if (seen.has(u)) continue;
      const age = pageAgeByUrl.get(u);
      const pubMs = parsePageAge(age);
      if (pubMs === null) { droppedNoDate++; continue; }
      if (pubMs < cutoffMs) { droppedOld++; continue; }
      seen.add(u);
      const sourceDate = new Date(pubMs).toISOString();
      urls.push({ url: u, source_date: sourceDate });
    }
  } catch (e) {}
}
const cap = Number(lens.cap || 25);
const capped = urls.slice(0, cap);
return [{ json: { lensId: lens.lensId, lensKey: lens.lensKey, sourceName: lens.sourceName, sourceCategory: lens.sourceCategory, startedAt: lens.startedAt, urlsEmitted: capped.length, urls: capped, droppedOld, droppedNoDate } }];

